SET time_zone='+00:00'; SET SESSION lock_wait_timeout=5; SET SESSION innodb_lock_wait_timeout=5; SET SESSION MAX_EXECUTION_TIME=5000;
SELECT m.id meeting_id,m.owner_id,m.revision,t.id task_id,t.state task_state,t.last_error,t.input_id,t.output_kind,t.output_id,e.id execution_id,e.state execution_state,e.request_hash,o.id operation_id,o.state operation_state,o.external_result_id,r.id permit_id,r.settled_at FROM meeting m JOIN durable_task t ON t.subject_id=m.id AND t.task_type='MINUTES_GENERATE_V1' LEFT JOIN external_execution e ON e.task_id=t.id LEFT JOIN external_operation o ON o.id=e.operation_id LEFT JOIN model_reservation r ON r.execution_id=e.id WHERE m.owner_id='task09-e5cd2e28-8c15-479e-bc51-bea8fcb6af50' OR e.id='7154f2fd-e931-4218-a87c-94dfc6d6ba68' ORDER BY m.id,t.id;
SELECT r.id permit_id,r.settled_at,r.execution_id,(SELECT COUNT(*) FROM model_reservation p WHERE p.id<=r.id) keyset_rank,(SELECT COUNT(*) FROM model_reservation) total_reservations FROM model_reservation r WHERE r.execution_id='7154f2fd-e931-4218-a87c-94dfc6d6ba68';
